{
  "families": [
    {
      "family": "pipelined",
      "ranges": [
        {"param": "data_width", "low": 22, "high": 28, "choices": null},
        {"param": "n_iter", "low": 20, "high": 30, "choices": null},
        {"param": "angle_guard", "low": -2, "high": 4, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 4, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]}
      ],
      "budget_share": 40,
      "why": "One result/cycle means the 50 MSPS constraint only needs Fmax >= 50 MHz, which is easily met; this family is the baseline for the area/power front. W >= 22 and N >= 20 are the minimum plausible settings for max_abs_err <= 2^-20, and the guards/rounding sweep the accuracy-vs-area trade-off."
    },
    {
      "family": "pipelined_m",
      "ranges": [
        {"param": "data_width", "low": 22, "high": 28, "choices": null},
        {"param": "n_iter", "low": 20, "high": 30, "choices": null},
        {"param": "angle_guard", "low": -2, "high": 4, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 4, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]},
        {"param": "m", "low": 2, "high": 8, "choices": null}
      ],
      "budget_share": 50,
      "why": "Also 1 result/cycle, but registering every m stages trades Fmax for fewer pipeline FFs, which is exactly the area objective here since only 50 MSPS is required. Sweeping m = 2..8 with the same accuracy box should reveal the low-area corner of the front."
    },
    {
      "family": "unrolled_k",
      "ranges": [
        {"param": "data_width", "low": 22, "high": 28, "choices": null},
        {"param": "n_iter", "low": 20, "high": 24, "choices": null},
        {"param": "angle_guard", "low": -2, "high": 4, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 4, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]},
        {"param": "k", "low": 6, "high": 8, "choices": null}
      ],
      "budget_share": 10,
      "why": "Small probe at the highest k (6..8) and shortest N (20..24) to test the best-case throughput of ceil(N/k)+3 cycles; if even this corner cannot reach 50 MSPS at a realistic Fmax for a 22+ bit datapath, the family is confirmed infeasible and the budget stays on the pipelined families."
    }
  ],
  "rationale": "The accuracy spec (max_abs_err <= 2^-20) forces roughly W >= 22 and N >= 20, and the 50 MSPS throughput constraint then eliminates the multi-cycle families: iterative needs N+3 ~ 23+ cycles (implying >1 GHz) and unrolled_k needs ceil(N/k)+3 cycles with k chained micro-rotations in one clock, which is very unlikely to reach the required clock on a 22+ bit datapath. Only pipelined and pipelined_m give 1 result/cycle, so Fmax >= 50 MHz is sufficient and the whole trade-off becomes area/power vs accuracy. Round 1 therefore maps both pipelined families broadly over data_width 22..28, n_iter 20..30, angle_guard -2..4, frac_guard 0..4 and both rounding modes, with pipelined_m additionally sweeping m = 2..8 (the main FF-saving knob), plus a 10% probe of unrolled_k at maximum k to confirm or refute its feasibility before later rounds concentrate the budget on the surviving front."
}

{
  "decision": "map_front",
  "rationale": "The feasible Pareto front currently contains a single design (pipelined_m, data_width=26, n_iter=22, angle_guard=0, frac_guard=0, rounding=round, m=6) at luts_plus_ffs=2260 and power_index=4.25, so front coverage is degenerate: luts_plus_ffs 2260..2260 against HV ref 8000 and power_index 4.25..4.25 against HV ref 20. Both objectives are essentially unmapped, and hypervolume can only improve by covering the rest of the trade-off curve. The two feasible families are pipelined (29/40 feasible, best luts_plus_ffs=4018, max throughput 264 MSPS) and pipelined_m (89/150 feasible, best luts_plus_ffs=2260, max throughput 158 MSPS); unrolled_k is infeasible (max throughput 6.52 MSPS < 50), and iterative is not worth spending budget on because its N+3 cycles/result at the N>=22 needed for 2^-20 accuracy implies well under 50 MSPS. Therefore this round should be spent mapping the whole front with NSGA-II over the full registry ranges of pipelined and pipelined_m, seeded with the current front, rather than refining a single-point front."
  ,
  "next_plan": null
}

{
  "decision": "map_front",
  "rationale": "The feasible Pareto front is a single point (pipelined_m, luts_plus_ffs=2260, power_index=4.25), covering only 2260..2260 of the area range (HV ref 8000) and 4.25..4.25 of the power range (HV ref 20). Hypervolume gain this round was +0.0%, so the current search has stagnated and the front is far too narrow to score well against the reference point. The remaining 100 evaluations are the reserved budget for mapping the front over the full ranges of the families on it. iterative cannot meet the 50 MSPS constraint (accuracy needs N>=20, so N+3>=23 cycles/result, requiring >1.15 GHz at 50 MSPS), and unrolled_k already produced 0 feasible designs (max throughput 6.52 MSPS). pipelined is feasible but dominated on area (best luts_plus_ffs=4018 vs 2260) and runs at a higher clock, so it is not on the front. Therefore the correct use of the final round is to run NSGA-II over the full pipelined_m ranges (data_width 8..28, n_iter 4..30, angle_guard -2..4, frac_guard 0..4, m 2..8), seeded with the current front, to map the whole trade-off curve and improve hypervolume."
  ,"next_plan": null
}
